<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";

export default {
  name: "StaffExchangeRequest",
  mixins: [processQuestionnaire, generalMixin],
  props: ["queries"],

  data() {
    return {
      // Backend contract (workflow not yet implemented — this is UI only):
      // POST /fhir/QuestionnaireResponse with this.fhir = {
      //   practitioner: "Practitioner/<me>",
      //   exchangingWith: "Practitioner/<partner>",
      //   currentPosition: "Basic/<my position>",
      //   destinationPosition: "Basic/<partner's position>",
      //   plannedTransferDate, transferReason,
      // }
      // maps onto StaffsExchangeLocationsProfile's extensions: practitioner,
      // staff-exchanging-with, current-position, destination-position,
      // planned-transfer-date, transfer-reason (status/event-date are set
      // server-side by the workflow, same as HOD Recommended Transfer).
      url: "http://ihris.org/fhir/Questionnaire/staffs-exchange-locations",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/staffs-exchange-locations-profile",

      loadingMyPosition: true,
      loadError: null,
      // Basic id of the staff's own most recent exchange request, if it's
      // still active (not cancelled/approved/rejected) — a staff member may
      // only have one active exchange request at a time, mirroring the
      // check the backend workflow itself enforces on submit.
      activeExchangeId: null,

      // Yearly cap — mirrors staffFacilityExchangeRequestWorkflow.js, which
      // is the source of truth. Checked here too so the form doesn't let
      // someone fill everything in only to be rejected on submit.
      maxRequestsPerYear: 3,
      yearlyLimitReached: false,
      yearlyRequestCount: 0,
      financialYearLabel: "",

      myPractitionerRef: null,
      myPractitionerName: "",
      myPosition: {
        reference: null,
        designation: "",
        department: "",
        facility: "",
        district: "",
        grade: "",
      },

      valid: false,
      saving: false,
      formSubmitted: false,
      transferDateMenu: false,

      form: {
        exchangePartner: {
          reference: null,
          display: "",
          gender: "",
          position: "",
          positionRef: null,
          facility: "",
          district: "",
        },
        plannedTransferDate: null,
        transferReason: "",
      },

      // ── Exchange partner picker ────────────────────────────────────
      partnerDialog: false,
      checkingPartner: false,
      partnerItems: [],
      partnerTotal: 0,
      loadingPartners: false,
      partnerOptions: { page: 1, itemsPerPage: 10 },
      partnerFilter: { name: "", position: "" },
      partnerDebounce: null,
      partnerHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Gender", value: "gender", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      // ── Facility filter tree (district → council → facility) ───────
      filterTreeOpen: false,
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {}, // 'Location/id' → { name, type: 'district'|'council'|'facility' }
        loading: false,
        displayValue: "",
      },

      rules: {
        required: (v) => !!v || "This field is required",
      },

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    minTransferDate() {
      return new Date().toISOString().substr(0, 10);
    },

    sameFacilityError() {
      return (
        !!this.myPosition.facility &&
        !!this.form.exchangePartner.facility &&
        this.myPosition.facility === this.form.exchangePartner.facility
      );
    },

    positionMismatchError() {
      return (
        !!this.myPosition.designation &&
        !!this.form.exchangePartner.position &&
        this.myPosition.designation !== this.form.exchangePartner.position
      );
    },
  },

  watch: {
    partnerOptions: {
      handler() {
        if (this.partnerDialog) this.fetchPartners();
      },
      deep: true,
    },
    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.partnerOptions.page = 1;
      this.fetchPartners();
    },
  },

  async mounted() {
    await this.loadMyPosition();
  },

  methods: {
    async loadMyPosition() {
      this.loadingMyPosition = true;
      this.loadError = null;
      try {
        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.loadError =
            "We could not confirm your staff account. Please try logging in again.";
          return;
        }

        // This page is reached via the generic Staff Section action-link
        // pattern (IhrisPagePractitioner.fsh), which substitutes whichever
        // practitioner's record is on screen into ?practitioner=. Requesting
        // an exchange only ever makes sense for yourself, so if that id is
        // present and doesn't match who's actually logged in — e.g. an HR
        // user viewing a colleague's record and following the link — refuse
        // rather than silently submitting a request as the logged-in user
        // under what looks like someone else's page.
        if (
          this.queries?.practitioner &&
          this.queries.practitioner !== practitionerId
        ) {
          this.loadError =
            "This staff exchange request page is only available for your own account.";
          return;
        }

        this.myPractitionerRef = "Practitioner/" + practitionerId;

        const hasActive = await this.checkActiveExchange();
        if (hasActive) return;

        const overLimit = await this.checkYearlyLimit();
        if (overLimit) return;

        const [nameRes, roleRes] = await Promise.all([
          fetch(`/fhir/Practitioner/${practitionerId}?_elements=name`),
          fetch(`/site/general/getCurrentRole/${practitionerId}`),
        ]);

        if (nameRes.ok) {
          const pract = await nameRes.json();
          const name = pract.name?.[0];
          this.myPractitionerName = name
            ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
            : "Unknown";
        }

        const role = roleRes.ok ? await roleRes.json() : null;
        const positionRef = role?.extension?.find(
          (e) =>
            e.url ===
            "http://ihris.org/fhir/StructureDefinition/position-reference",
        )?.valueReference?.reference;

        if (!positionRef) {
          this.loadError =
            "We could not find your current position. Please contact HR before requesting an exchange.";
          return;
        }

        await this.loadPosition(positionRef);
      } catch (err) {
        console.error("loadMyPosition error:", err);
        this.loadError =
          "Something went wrong loading your position details. Please try again.";
      } finally {
        this.loadingMyPosition = false;
      }
    },

    // A staff member may only have one active exchange request at a time
    // (with anyone, not just a specific partner) — mirrors the check
    // staffFacilityExchangeRequestWorkflow.js itself enforces on submit.
    // Checked up front here so the form doesn't let someone fill out the
    // whole thing only to be rejected at the very end.
    async checkActiveExchange() {
      try {
        const params = new URLSearchParams({
          _profile: this.profile,
          practitioner: this.myPractitionerRef,
          _sort: "-eventdate",
          _count: 1,
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        const bundle = await res.json();
        const latest = bundle.entry?.[0]?.resource;
        if (!latest) return false;

        const status = latest.extension?.find((e) =>
          e.url.includes("request-status"),
        )?.valueCoding?.code;
        // Terminal states — anything else still counts as in-flight and
        // blocks a fresh request. Note psapproved/hodapplied are NOT
        // terminal: the exchange is approved but still waiting on the
        // District HOD(s) to apply it, so it must keep blocking until it
        // reaches "completed". "approved"/"rejected" are kept only for
        // legacy data — this feature only ever produces the ps* variants.
        const isActive =
          status &&
          ![
            "cancelled",
            "completed",
            "psrejected",
            "approved",
            "rejected",
          ].includes(status);
        if (isActive) {
          this.activeExchangeId = latest.id;
          return true;
        }
        return false;
      } catch (err) {
        console.error("checkActiveExchange error:", err);
        // Fail open — don't block the form on a network hiccup; the
        // backend workflow is the source of truth either way.
        return false;
      }
    },

    // Lesotho financial year runs 1 April - 31 March, matching
    // utils.getFinancialYear() on the backend.
    currentFinancialYear() {
      const now = new Date();
      const startYear =
        now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
      return {
        start: `${startYear}-04-01`,
        end: `${startYear + 1}-03-31`,
        label: `${startYear}/${startYear + 1}`,
      };
    },

    // Counts this staff member's requests in the current financial year.
    // A cancelled request only counts if at least one reviewer had already
    // acted on it — withdrawing before anyone spent time costs nothing.
    async checkYearlyLimit() {
      try {
        const fy = this.currentFinancialYear();
        this.financialYearLabel = fy.label;

        const params = new URLSearchParams({
          _profile: this.profile,
          practitioner: this.myPractitionerRef,
          _count: 200,
        });
        params.append("eventdate", "ge" + fy.start);
        params.append("eventdate", "le" + fy.end);

        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) return false;
        const bundle = await res.json();

        let counted = 0;
        const cancelledIds = [];
        for (const entry of bundle.entry || []) {
          const status = entry.resource.extension?.find((e) =>
            e.url.includes("request-status"),
          )?.valueCoding?.code;
          if (status === "cancelled") {
            cancelledIds.push(entry.resource.id);
          } else {
            counted++;
          }
        }

        if (cancelledIds.length) {
          counted += await this.countReviewedRequests(cancelledIds);
        }

        this.yearlyRequestCount = counted;
        if (counted >= this.maxRequestsPerYear) {
          this.yearlyLimitReached = true;
          return true;
        }
        return false;
      } catch (err) {
        console.error("checkYearlyLimit error:", err);
        // Fail open — the backend workflow enforces this regardless.
        return false;
      }
    },

    // How many of the given requests have at least one review against them.
    // Wrapped defensively: if the search parameter isn't indexed on the FHIR
    // server yet this must not block the form, so a failure here simply
    // leaves cancelled requests uncounted.
    async countReviewedRequests(requestIds) {
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/review-staff-exchange-location-profile",
          staffexchangelocationreference: requestIds
            .map((id) => "Basic/" + id)
            .join(","),
          _count: 200,
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) return 0;
        const bundle = await res.json();

        const reviewed = new Set();
        for (const entry of bundle.entry || []) {
          const ref = entry.resource.extension?.find((e) =>
            e.url.includes("staff-exchange-location-reference"),
          )?.valueReference?.reference;
          if (ref) reviewed.add(ref.split("/")[1]);
        }
        return requestIds.filter((id) => reviewed.has(id)).length;
      } catch (err) {
        console.error("countReviewedRequests error:", err);
        return 0;
      }
    },

    viewActiveExchange() {
      this.$router.push({
        path: "/custom/staff-exchange-view",
        query: {
          path: "/lesotho/components/transfers",
          id: this.activeExchangeId,
          returnLabel: "Back to Exchange Requests",
        },
      });
    },

    async loadPosition(ref) {
      const id = ref.includes("/") ? ref.split("/")[1] : ref;
      const res = await fetch(`/fhir/Basic/${id}`);
      if (!res.ok) throw new Error("Could not load position " + ref);
      const position = await res.json();
      const getExt = (part, type) =>
        position.extension?.find((e) => e.url.includes(part))?.[type];

      let designation = "";
      const designationRef = getExt("designation", "valueReference")
        ?.reference;
      if (designationRef) {
        try {
          const dId = designationRef.split("/")[1];
          const dRes = await fetch(`/fhir/Basic/${dId}`);
          const dData = await dRes.json();
          designation =
            dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
              ?.valueString || "";
        } catch {
          // designation lookup best-effort
        }
      }

      let facility = "";
      const facilityRef = getExt("facility", "valueReference")?.reference;
      if (facilityRef) {
        try {
          const fId = facilityRef.split("/")[1];
          const fRes = await fetch(`/fhir/Location/${fId}`);
          const fData = await fRes.json();
          facility = fData.name || "";
        } catch {
          // facility lookup best-effort
        }
      }

      this.myPosition = {
        reference: ref,
        designation,
        department: getExt("department", "valueCoding")?.display || "",
        facility,
      };
    },

    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    goBack() {
      this.$router.go(-1);
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    formatDate(dateString) {
      if (!dateString) return "";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    // ── Exchange partner picker ─────────────────────────────────────
    debouncedFetchPartners() {
      clearTimeout(this.partnerDebounce);
      this.partnerDebounce = setTimeout(() => {
        this.partnerOptions.page = 1;
        this.fetchPartners();
      }, 350);
    },

    async fetchPartners() {
      this.loadingPartners = true;
      try {
        const params = new URLSearchParams({
          page: this.partnerOptions.page,
          count: this.partnerOptions.itemsPerPage,
        });
        if (this.partnerFilter.name)
          params.set("name", this.partnerFilter.name);
        if (this.partnerFilter.position)
          params.set("position", this.partnerFilter.position);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.partnerTotal = data.total || 0;
        const items = data.supervisors || [];

        // /site/position/supervisors doesn't return gender, so resolve it
        // separately per candidate — mirrors how reviewer/requester names
        // are resolved elsewhere in this feature.
        await Promise.all(
          items.map(async (item) => {
            if (!item.practitionerRef) return;
            try {
              const id = item.practitionerRef.split("/")[1];
              const r = await fetch(
                `/fhir/Practitioner/${id}?_elements=gender`,
              );
              const pract = await r.json();
              item.gender = pract.gender
                ? pract.gender.charAt(0).toUpperCase() +
                  pract.gender.slice(1)
                : "";
            } catch {
              item.gender = "";
            }
          }),
        );

        this.partnerItems = items;
      } catch (err) {
        console.error("fetchPartners error", err);
      } finally {
        this.loadingPartners = false;
      }
    },

    // Same position (by designation display), different facility, and
    // never yourself.
    isSelectablePartner(item) {
      if (!item.practitionerRef) return false;
      if (item.practitionerRef === this.myPractitionerRef) return false;
      if (
        this.myPosition.facility &&
        item.facility &&
        item.facility === this.myPosition.facility
      ) {
        return false;
      }
      if (
        this.myPosition.designation &&
        item.position &&
        item.position !== this.myPosition.designation
      ) {
        return false;
      }
      return true;
    },

    partnerSelectHint(item) {
      if (item.practitionerRef === this.myPractitionerRef) {
        return "You cannot select yourself";
      }
      if (item.facility && item.facility === this.myPosition.facility) {
        return "Must be at a different facility from you";
      }
      if (
        this.myPosition.designation &&
        item.position &&
        item.position !== this.myPosition.designation
      ) {
        return "Must hold the same position as you";
      }
      return "Select this staff member";
    },

    async selectPartner(item) {
      if (!this.isSelectablePartner(item)) {
        this.showSnackbar(this.partnerSelectHint(item), "error");
        return;
      }
      this.checkingPartner = true;
      try {
        this.form.exchangePartner = {
          reference: item.practitionerRef,
          display: item.name,
          gender: item.gender || "",
          position: item.position || "",
          positionRef: item.positionRef || null,
          facility: item.facility || "",
          district: "",
        };
        this.partnerDialog = false;
        this.resolvePartnerDistrict(item.positionRef);
      } finally {
        this.checkingPartner = false;
      }
    },

    // /site/position/supervisors doesn't return a facility id (only its
    // name), so the district can't be resolved directly from the picker
    // row — go through the partner's position instead, same as how our
    // own position's district gets resolved.
    async resolvePartnerDistrict(positionRef) {
      if (!positionRef) return;
      try {
        const id = this.refId(positionRef);
        const res = await fetch(`/fhir/Basic/${id}`);
        if (!res.ok) return;
        const position = await res.json();
        const facilityRef = position.extension?.find((e) =>
          e.url.includes("facility"),
        )?.valueReference?.reference;
        if (!facilityRef) return;
        const district = await this.resolveDistrict(facilityRef);
        this.form.exchangePartner.district = district;
      } catch (err) {
        console.error("resolvePartnerDistrict error:", err);
      }
    },

    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    // Walk Location.partOf up the hierarchy (facility → council → district)
    // until a Location tagged with the district profile is found.
    async resolveDistrict(facilityRef) {
      try {
        let ref = facilityRef;
        for (let i = 0; i < 5 && ref; i++) {
          const id = this.refId(ref);
          if (!id) return "";
          const res = await fetch(`/fhir/Location/${id}`);
          if (!res.ok) return "";
          const loc = await res.json();
          if (loc.meta?.profile?.some((p) => p.includes("ls-district"))) {
            return loc.name || "";
          }
          ref = loc.partOf?.reference;
        }
        return "";
      } catch (error) {
        console.error("Error resolving district:", error);
        return "";
      }
    },

    clearPartner() {
      this.form.exchangePartner = {
        reference: null,
        display: "",
        gender: "",
        position: "",
        positionRef: null,
        facility: "",
        district: "",
      };
    },

    // ── Facility filter tree ────────────────────────────────────────
    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    async fetchFilterChildren(item) {
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      try {
        const r = await fetch(`/fhir/Location?partof=${item.id}&_count=200`);
        const data = await r.json();
        const children = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
          };
          if (childType === "council") node.children = [];
          this.filterTree.treeLookup[node.id] = {
            name: node.name,
            type: childType,
          };
          return node;
        });
        item.children.push(...children);
      } catch (err) {
        console.error("fetchFilterChildren error", err);
      }
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    async submitForm() {
      this.formSubmitted = true;
      const valid = this.$refs.form.validate();
      if (!valid || !this.form.exchangePartner.reference) {
        this.showSnackbar("Please complete all required fields.", "error");
        return;
      }
      if (this.sameFacilityError) {
        this.showSnackbar(
          "Exchange partner must be at a different facility from you.",
          "error",
        );
        return;
      }
      if (this.positionMismatchError) {
        this.showSnackbar(
          "Exchange partner must hold the same position as you.",
          "error",
        );
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          practitioner: this.myPractitionerRef,
          exchangingWith: this.form.exchangePartner.reference,
          currentPosition: this.myPosition.reference,
          destinationPosition: this.form.exchangePartner.positionRef,
          plannedTransferDate: this.form.plannedTransferDate,
          transferReason: this.form.transferReason,
        };
        this.afterSaveMessage = "Exchange request submitted successfully!";
        await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 200);
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar(
          "Failed to submit exchange request. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },
  },

  created() {
    this.loadFilterTree();
  },
};
</script>

