import store from "@/store";

export default {
  data: function() {
    return {
      loggedInStaff: {
        supervisor: {},
        department: {},
        practitioner: "",
        gender: "",
        name: "",
      },
      practitionerProfile: {
        supervisor: {},
        department: {},
        gender: "",
        name: "",
      },
      loadingUserData: true,
      loadingSupervisor: true,
    };
  },

  methods: {
    /**
     * Waits for store.state.user.obj.resource to be populated
     * Returns a promise that resolves when user data is available
     */
    waitForUserData() {
      return new Promise((resolve) => {
        // Check if data already exists
        if (store.state.user?.obj?.resource) {
          resolve();
          return;
        }

        // Watch for changes in the store
        const unwatch = this.$watch(
          () => store.state.user?.obj?.resource,
          (newValue) => {
            if (newValue) {
              unwatch(); // Stop watching
              resolve();
            }
          },
          { immediate: true },
        );

        // Timeout after 10 seconds to prevent infinite waiting
        setTimeout(() => {
          unwatch();
          console.error("Timeout waiting for user data in store");
          resolve(); // Resolve anyway to prevent hanging
        }, 20000);
      });
    },

    /**
     * Gets user department and staff information
     * Only runs after user data is available in store
     */
    getUserData: async function(practitioner, obj) {
      try {
        let response = await fetch(
          "/site/general/getPractitionerData/" + practitioner,
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        let data = await response.json();
        for (let dt in data) {
          obj[dt] = data[dt];
        }
        return obj;
      } catch (error) {
        console.error("Error in getUserData:", error);
      }
    },
  },

  async created() {
    this.loadingUserData = true;
    // Wait for user data to be available in store
    await this.waitForUserData();

    if (!store.state.user?.obj?.resource?.extension) {
      this.loadingUserData = false;
      return;
    }

    let practitioner = store.state.user.obj.resource.extension.find((ext) => {
      return (
        ext.url ===
        "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
      );
    })?.valueReference?.reference;
    if (!practitioner) {
      console.error("Practitioner reference not found");
      this.loadingUserData = false;
      return;
    }
    this.loggedInStaff.practitioner = practitioner.split("/")[1];
    await this.getUserData(this.loggedInStaff.practitioner, this.loggedInStaff);
    if (this.queries?.practitioner) {
      await this.getUserData(
        this.queries.practitioner,
        this.practitionerProfile,
      );
    }
    this.loadingUserData = false;
  },
};
